+// The audit trail: one entry per request that changes data.
+
+/** Appends an audit entry (time, key name, method, path, status). */
+export function recordAudit(store, { at, key, method, path, status }) {
+  (store.data.audit ??= []).push({ at, key, method, path, status });
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse();
+}
