+// API keys and roles. Keys live in the data as apiKeys: [{ key, name, role }].
+import { AppError } from "../errors.js";
+
+/** The roles, from least to most powerful. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+// Writes a cook may do besides reading.
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+// Reads only managers may do.
+const MANAGER_READS = [/^\/audit$/];
+
+/** Finds the key record behind the Authorization header; throws 401 if none. */
+export function authenticate(store, headers) {
+  const header = Object.entries(headers).find(([k]) => k.toLowerCase() === "authorization")?.[1];
+  const m = /^Bearer\s+(\S+)\s*$/i.exec(String(header ?? ""));
+  if (!m) throw new AppError("unauthorized");
+  const found = (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws 403 unless `role` may make this request. */
+export function authorize(role, method, path) {
+  if (role === "manager") return;
+  const read = method === "GET" || method === "HEAD";
+  if (read) {
+    if (MANAGER_READS.some((re) => re.test(path))) throw new AppError("forbidden");
+    return;
+  }
+  if (role === "cook" && COOK_WRITES.some(([m, re]) => m === method && re.test(path))) return;
+  throw new AppError("forbidden");
+}
